function countGoodTriplets(arr, a, b, c) {
  const n = arr.length;
  let count = 0;

  for (let i = 0; i < n - 2; i++) {
    for (let j = i + 1; j < n - 1; j++) {
      if (Math.abs(arr[i] - arr[j]) > a) {
        continue;
      }
      for (let k = j + 1; k < n; k++) {
        const okJK = Math.abs(arr[j] - arr[k]) <= b;
        const okIK = Math.abs(arr[i] - arr[k]) <= c;
        if (okJK && okIK) {
          count++;
        }
      }
    }
  }
  return count;
}

brute:
function countGoodTriplets(arr, a, b, c) {
  // Build every 3-index combination recursively, then test each one.
  const picks = [];
  const choose = (start, chosen) => {
    if (chosen.length === 3) { picks.push(chosen); return; }
    for (let t = start; t < arr.length; t++) choose(t + 1, [...chosen, t]);
  };
  choose(0, []);
  return picks.filter(([x, y, z]) => {
    const dxy = arr[x] - arr[y], dyz = arr[y] - arr[z], dxz = arr[x] - arr[z];
    return -a <= dxy && dxy <= a && -b <= dyz && dyz <= b && -c <= dxz && dxz <= c;
  }).length;
}

