function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  if (size === 'large') {
    const top = rand() < 0.5 ? 1000 : int(10, 200);
    const arr = Array.from({ length: 100 }, () => int(0, top));
    const limit = () => int(0, Math.max(1, Math.floor(top / 2)));
    return [arr, limit(), limit(), limit()];
  }
  const n = int(3, 9);
  const top = rand() < 0.3 ? 3 : rand() < 0.6 ? 12 : 1000;
  const arr = Array.from({ length: n }, () => int(0, top));
  const limit = () => rand() < 0.15 ? 0 : int(0, top);
  return [arr, limit(), limit(), limit()];
}
